    emit ExcessCapitalWithdrawn(amount, msg.sender, positionId);

    // Transfer the excess capital to the investor
    if (amount > 0) SafeTransferLib.safeTransfer(s_capitalRaiseConfig.bidToken, msg.sender, amount);
}

